// Whirlpool – Detail-Reel 9:16. Deterministic, frame-addressed motion graphics:
// window.COMP.seek(n) puts the stage into the exact state of output frame n.
// Footage timing (cuts, slow motion) comes from timeline.js, generated by
// scripts/retime.py from edit.json; one plate per output frame.
//
// Graphics: one #0f2334 glass box per section that settles into a hover state
// (lift, brighter edge, drifting light spot, one sheen pass). The type inside is
// animated like TextAnimate with the "blurInUp" preset.
// Text is split by character / word, segments stagger over `duration`
// (stagger = duration / segments) and leave in reverse order before the next cut.
(() => {
  const { FPS, TOTAL, SHOTS } = window.TIMELINE;
  const params = new URLSearchParams(location.search);
  const PLATE_DIR = params.get('plates') || '../../build/whirlpool/plates';

  const ORDER = ['intro', 'B', 'C', 'D', 'E', 'F', 'G'];
  const START = { intro: 0, B: SHOTS.B.start, C: SHOTS.C.start, D: SHOTS.D.start, E: SHOTS.E.start, F: SHOTS.F.start, G: SHOTS.G.start };
  const T = {
    intro: 0.20,          // first title starts after the opening frames
    enter: 0.22,          // section text starts this long after its cut...
    exitLead: 0.20,       // ...and starts leaving this long before the next cut
    exitDur: 0.15,        // exit stagger span
    exitItem: 0.28,       // exit duration per segment (faster than the entry)
  };
  // blurInUp, scaled from web px to the 1080 px canvas (≈2×).
  const V = { y: 36, blur: 18, dY: 0.3, dOpacity: 0.4, dBlur: 0.3 };

  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
  const prog = (t, start, dur) => clamp((t - start) / dur);
  const easeOut = k => 1 - (1 - k) * (1 - k);
  const inOut = k => (k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2);

  const el = { plate: $('#plate'), blocks: Object.fromEntries($$('.txt').map(b => [b.dataset.sec, b])) };

  // Split every text element into segments (TextAnimate `by`).
  function split(node) {
    const by = node.dataset.by;
    if (by === 'text' || node.tagName === 'IMG') return [node];
    const text = node.textContent;
    const parts = by === 'character' ? [...text] : text.split(/(\s+)/);
    node.textContent = '';
    return parts.map(p => {
      const s = document.createElement('span');
      s.className = 'seg';
      s.textContent = p;
      node.appendChild(s);
      return s;
    });
  }
  const groups = Object.fromEntries(ORDER.map(sec => [sec, $$('[data-by]', el.blocks[sec]).map(node => ({
    segs: split(node),
    delay: parseFloat(node.dataset.delay || 0),
    dur: parseFloat(node.dataset.dur || 0.3),
  }))]));

  // Section window: text enters after the cut, has left before the next one.
  const secWindow = sec => {
    const i = ORDER.indexOf(sec), next = ORDER[i + 1];
    const tin = sec === 'intro' ? T.intro : START[sec] + T.enter;
    return { tin, tout: next ? START[next] - T.exitLead : Infinity, next };
  };

  function segState(seg, t, start, end) {
    // show: hidden → visible; exit: visible → hidden (blurInUp exits downwards).
    const out = easeOut(prog(t, end, T.exitItem));
    const ky = easeOut(prog(t, start, V.dY)) * (1 - out);
    const ko = easeOut(prog(t, start, V.dOpacity)) * (1 - out);
    const kb = easeOut(prog(t, start, V.dBlur)) * (1 - out);
    seg.style.opacity = ko.toFixed(3);
    seg.style.transform = `translateY(${((1 - ky) * V.y).toFixed(1)}px)`;
    seg.style.filter = kb > 0.995 ? 'none' : `blur(${((1 - kb) * V.blur).toFixed(2)}px)`;
  }

  // Glass box: arrives just ahead of its text, hovers once the text is in,
  // leaves after the last segment has gone.
  function glass(box, t, tin, tout) {
    const kin = easeOut(prog(t, tin - 0.1, 0.4));
    const kout = easeOut(prog(t, tout + 0.12, 0.3));
    const k = kin * (1 - kout);
    const h = inOut(prog(t, tin + 0.45, 0.5)) * (1 - easeOut(prog(t, tout - 0.1, 0.25)));
    box.style.opacity = k.toFixed(3);
    box.style.transform = `translateY(${((1 - kin) * 28 + kout * 28 - 8 * h).toFixed(1)}px) scale(${(0.985 + 0.015 * kin + 0.012 * h).toFixed(4)})`;
    box.style.filter = k > 0.995 ? 'none' : `blur(${((1 - k) * 8).toFixed(2)}px)`;
    box.style.setProperty('--h', h.toFixed(3));
    // Light spot follows a slow cursor path over the glass.
    const u = t - tin;
    box.style.setProperty('--mx', `${(50 + 38 * Math.sin(u * 1.3)).toFixed(1)}%`);
    box.style.setProperty('--my', `${(40 + 30 * Math.sin(u * 0.9 + 1.2)).toFixed(1)}%`);
    box.style.setProperty('--sx', `${(-120 + 240 * inOut(prog(t, tin + 0.5, 0.9))).toFixed(1)}%`);
  }

  function render(n) {
    const t = n / FPS;
    for (const sec of ORDER) {
      const { tin, tout } = secWindow(sec);
      const live = t >= tin - 0.1 && t < tout + 0.45;
      el.blocks[sec].style.visibility = live ? 'visible' : 'hidden';
      if (!live) continue;
      glass(el.blocks[sec], t, tin, tout);
      for (const g of groups[sec]) {
        const N = g.segs.length;
        g.segs.forEach((seg, i) => {
          const start = tin + g.delay + i * (g.dur / N);
          const end = tout + (N - 1 - i) * (T.exitDur / N);   // staggerDirection: -1
          segState(seg, t, start, end);
        });
      }
    }
  }

  async function seek(n) {
    const idx = String(Math.min(n, TOTAL - 1)).padStart(4, '0');
    if (el.plate.dataset.idx !== idx) {
      el.plate.src = `${PLATE_DIR}/f${idx}.jpg`;
      await el.plate.decode();
      el.plate.dataset.idx = idx;
    }
    render(n);
  }

  async function init() {
    await Promise.all([400, 500, 600, 700].map(w => document.fonts.load(`${w} 40px Poppins`)));
    await document.fonts.ready;
    await $('.logo').decode();
    const t0 = params.get('t');
    await seek(t0 ? Math.round(parseFloat(t0) * FPS) : 0);
  }

  window.COMP = { FPS, TOTAL, seek, ready: init() };
})();
